<?php declare(strict_types=1);
$documentSourceState??=\Kulturhus\Verein\Web\DocumentSourcePage::prepare($documents,$_GET);$sp=$documentSourceState['page'];$sf=$documentSourceState['filters'];$sq=static fn(string$key):string=>is_string($sf[$key]??null)?$sf[$key]:'';$base=['view'=>'documents','doc_mode'=>'sources'];$filters=['q'=>$sq('q'),'source_kind'=>$sq('source_kind'),'scope'=>$sq('scope')];$sourcePageLabel=$documentFormat('Vorgangsseite {page} von {pages} · {count} Treffer',['page'=>$sp['page']??0,'pages'=>$sp['pages']??0,'count'=>$sp['total']??0]);
?>
<section data-document-source-overview><h2><?= e($documentText('Vorgänge ohne abgelegte Datei')) ?></h2><p><?= e($documentText('Hier erscheinen zugängliche Vorgänge, denen für dich keine lesbare aktive Datei zugeordnet ist. Geschützte Ordner und Dateien anderer Berechtigungsbereiche werden berücksichtigt.')) ?></p>
<form method="get" class="card doc-filter" data-document-source-search><?= hidden('view','documents').hidden('doc_mode','sources').hidden('page','1') ?><label><?= e($documentText('Vorgangsname oder Ordner suchen')) ?><input class="form-control" type="search" name="q" maxlength="150" value="<?= e($sq('q')) ?>"></label>
<label><?= e($documentText('Vorgangsart')) ?><select class="form-control" name="source_kind"><option value=""><?= e($documentText('Alle Vorgangsarten')) ?></option><?php if($sq('source_kind')!==''&&!isset(\Kulturhus\Verein\DocumentCatalog::TYPES[$sq('source_kind')])): ?><option value="<?= e($sq('source_kind')) ?>" selected><?= e($documentText('Vorgangsart prüfen.')) ?></option><?php endif;foreach(\Kulturhus\Verein\DocumentCatalog::TYPES as$key=>$label): ?><option value="<?= e($key) ?>" <?= $sq('source_kind')===$key?'selected':'' ?>><?= e($documentText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($documentText('Berechtigungsbereich')) ?><select class="form-control" name="scope"><option value=""><?= e($documentText('Alle Bereiche')) ?></option><?php if($sq('scope')!==''&&(!isset(\Kulturhus\Verein\DocumentCatalog::SCOPES[$sq('scope')])||!$documents->canScope($sq('scope')))): ?><option value="<?= e($sq('scope')) ?>" selected><?= e($sq('scope')) ?> · <?= e($documentText('Bitte Bereich prüfen')) ?></option><?php endif;foreach(\Kulturhus\Verein\DocumentCatalog::SCOPES as$key=>$label):if(!$documents->canScope($key))continue; ?><option value="<?= $key ?>" <?= $sq('scope')===$key?'selected':'' ?>><?= e($documentText($label)) ?></option><?php endforeach ?></select></label><button class="btn btn-solid theme-primary"><?= e($documentText('Vorgänge suchen')) ?></button><a class="btn btn-outline theme-secondary" href="<?= e(url($base)) ?>"><?= e($documentText('Suche zurücksetzen')) ?></a></form>
<?php if($documentSourceState['error']!==''): ?><p role="alert"><?= e($documentText($documentSourceState['error'])) ?></p><?php endif ?>
<?php if(array_filter($sf,static fn($value)=>!is_string($value))||!is_string($documentSourceState['number'])): ?><details><summary><?= e($documentText('Suchangaben prüfen')) ?></summary><pre><?= e(json_encode(['filters'=>$sf,'page'=>$documentSourceState['number']],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE)) ?></pre></details><?php endif ?>
<?php if($sp!==null): ?><p role="status"><?= e($sourcePageLabel) ?></p><div class="doc-source-results"><?php foreach($sp['rows']as$row):$record=\Kulturhus\Verein\DocumentCatalog::route($row['source_type'],$row['source_id']);$storage=['view'=>'documents','source_type'=>$row['source_type'],'source_id'=>$row['source_id']]; ?><article class="card" data-doc-source-row="<?= e($row['source_type'].':'.$row['source_id']) ?>"><small><?= e($documentText(\Kulturhus\Verein\DocumentCatalog::TYPES[$row['source_type']])) ?></small><h3><?= e($row['label']) ?></h3><p class="doc-path"><?= e($row['path']) ?></p><div class="doc-actions"><?php if($row['writable']): ?><a class="btn btn-solid theme-primary" data-doc-source-attach href="<?= e(url($storage+['new_document'=>1])) ?>"><?= e($documentText('Datei diesem Vorgang zuordnen')) ?></a><?php else: ?><a class="btn btn-outline theme-secondary" data-doc-source-storage href="<?= e(url($storage)) ?>"><?= e($documentText('Ablage ansehen')) ?></a><?php endif ?><a class="btn btn-outline theme-secondary" data-doc-source-record href="<?= e(url($record)) ?>"><?= e($documentText('Vorgang öffnen')) ?></a></div></article><?php endforeach ?></div>
<?php if(!$sp['rows']): ?><p><?= e($documentText('Keine zugänglichen Vorgänge ohne sichtbare aktive Datei passen zu diesen Filtern.')) ?></p><?php endif ?>
<nav class="doc-actions" aria-label="<?= e($documentText('Vorgangsseiten')) ?>"><?php if($sp['page']>1): ?><a class="btn btn-outline theme-secondary" data-doc-source-previous href="<?= e(url($base+$filters+['page'=>$sp['page']-1])) ?>"><?= e($documentText('Vorherige')) ?></a><?php endif;if($sp['page']<$sp['pages']): ?><a class="btn btn-outline theme-secondary" data-doc-source-next href="<?= e(url($base+$filters+['page'=>$sp['page']+1])) ?>"><?= e($documentText('Nächste')) ?></a><?php endif ?></nav><?php endif ?>
<form method="get" class="card doc-filter" data-document-source-page><?php foreach($base+$filters as$key=>$value)echo hidden($key,$value); ?><label><?= e($documentText('Vorgangsseite')) ?><input class="form-control" name="page" inputmode="numeric" pattern="[1-9][0-9]{0,8}" value="<?= e($sp!==null?(string)$sp['page']:(is_string($documentSourceState['number'])?$documentSourceState['number']:'')) ?>" required></label><button class="btn btn-outline theme-secondary"><?= e($documentText('Seite öffnen')) ?></button></form>
</section>
